datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id          Int          @id @default(autoincrement())
  username    String       @unique
  documents   Document[]   @relation("DocumentOwner")
  versions    Version[]
  permissions Permission[]
}

model Document {
  id          Int          @id @default(autoincrement())
  title       String
  content     String       @default("")
  ownerId     Int
  owner       User         @relation("DocumentOwner", fields: [ownerId], references: [id])
  versions    Version[]
  permissions Permission[]
  createdAt   DateTime     @default(now())
  updatedAt   DateTime     @updatedAt
}

model Version {
  id         Int      @id @default(autoincrement())
  documentId Int
  document   Document @relation(fields: [documentId], references: [id], onDelete: Cascade)
  content    String
  authorId   Int
  author     User     @relation(fields: [authorId], references: [id])
  createdAt  DateTime @default(now())
}

model Permission {
  id         Int      @id @default(autoincrement())
  documentId Int
  document   Document @relation(fields: [documentId], references: [id], onDelete: Cascade)
  userId     Int
  user       User     @relation(fields: [userId], references: [id])
  role       String   // "VIEW" or "EDIT"
  @@unique([documentId, userId])
}

import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  username: (data) => {
    if (typeof data.username !== "string") {
      throw new Error("Username is required.");
    }
    return data.username;
  },
});

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { DocumentPage } from "./src/DocumentPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { userSignupFields } from "./src/auth" with { type: "ref" };
import { webSocketFn } from "./src/webSocket" with { type: "ref" };

import { getDocuments, getDocument } from "./src/queries" with { type: "ref" };
import {
  createDocument,
  updateDocumentContent,
  saveVersion,
  restoreVersion,
  shareDocument,
  revokePermission,
} from "./src/actions" with { type: "ref" };

export default app({
  name: "app",
  title: "Real-time Collaborative Document Editor",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
  },
  webSocket: {
    fn: webSocketFn,
  },
  spec: [
    route("SignupRoute", "/signup", page(SignupPage)),
    route("LoginRoute", "/login", page(LoginPage)),
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("DocumentRoute", "/document/:id", page(DocumentPage, { authRequired: true })),

    query(getDocuments, { entities: ["Document", "Permission"] }),
    query(getDocument, { entities: ["Document", "Permission", "User", "Version"] }),

    action(createDocument, { entities: ["Document"] }),
    action(updateDocumentContent, { entities: ["Document", "Permission"] }),
    action(saveVersion, { entities: ["Document", "Version", "Permission"] }),
    action(restoreVersion, { entities: ["Document", "Version", "Permission"] }),
    action(shareDocument, { entities: ["Document", "Permission", "User"] }),
    action(revokePermission, { entities: ["Document", "Permission"] }),
  ],
});

import { type GetDocuments, type GetDocument } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getDocuments: GetDocuments<void, any[]> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  return context.entities.Document.findMany({
    where: {
      OR: [
        { ownerId: context.user.id },
        {
          permissions: {
            some: {
              userId: context.user.id,
            },
          },
        },
      ],
    },
    include: {
      owner: true,
      permissions: {
        include: {
          user: true,
        },
      },
    },
    orderBy: {
      updatedAt: "desc",
    },
  });
};

export const getDocument: GetDocument<{ id: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: {
      owner: true,
      permissions: {
        include: {
          user: true,
        },
      },
      versions: {
        include: {
          author: true,
        },
        orderBy: {
          createdAt: "asc", // Display in chronological order
        },
      },
    },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === context.user.id;
  const userPermission = doc.permissions.find((p) => p.userId === context.user.id);

  if (!isOwner && !userPermission) {
    throw new HttpError(403, "Access Denied");
  }

  const role = isOwner ? "OWNER" : userPermission?.role;

  return {
    ...doc,
    role,
  };
};

import {
  type CreateDocument,
  type UpdateDocumentContent,
  type SaveVersion,
  type RestoreVersion,
  type ShareDocument,
  type RevokePermission,
} from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const createDocument: CreateDocument<{ title: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }
  if (!args.title || args.title.trim() === "") {
    throw new HttpError(400, "Title is required");
  }
  return context.entities.Document.create({
    data: {
      title: args.title,
      content: "",
      ownerId: context.user.id,
    },
  });
};

export const updateDocumentContent: UpdateDocumentContent<{ id: number; content: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  const isOwner = doc.ownerId === context.user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === context.user.id && p.role === "EDIT"
  );
  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied: You do not have edit permission");
  }
  return context.entities.Document.update({
    where: { id: args.id },
    data: { content: args.content },
  });
};

export const saveVersion: SaveVersion<{ id: number; content: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  const isOwner = doc.ownerId === context.user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === context.user.id && p.role === "EDIT"
  );
  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied: You do not have edit permission");
  }

  const version = await context.entities.Version.create({
    data: {
      documentId: args.id,
      content: args.content,
      authorId: context.user.id,
    },
  });

  await context.entities.Document.update({
    where: { id: args.id },
    data: { content: args.content },
  });

  return version;
};

export const restoreVersion: RestoreVersion<{ id: number; versionId: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  const isOwner = doc.ownerId === context.user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === context.user.id && p.role === "EDIT"
  );
  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied: You do not have edit permission");
  }

  const version = await context.entities.Version.findUnique({
    where: { id: args.versionId },
  });
  if (!version || version.documentId !== args.id) {
    throw new HttpError(404, "Version not found");
  }

  const updatedDoc = await context.entities.Document.update({
    where: { id: args.id },
    data: { content: version.content },
  });

  const { ioInstance } = await import("./webSocket");
  if (ioInstance) {
    ioInstance.to(`document-${args.id}`).emit("document-restored", version.content);
  }

  return updatedDoc;
};

export const shareDocument: ShareDocument<{ id: number; username: string; role: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  if (doc.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can share the document");
  }

  const targetUser = await context.entities.User.findUnique({
    where: { username: args.username },
  });
  if (!targetUser) {
    throw new HttpError(404, "User not found");
  }

  if (targetUser.id === context.user.id) {
    throw new HttpError(400, "You cannot share the document with yourself");
  }

  return context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId: args.id,
        userId: targetUser.id,
      },
    },
    update: {
      role: args.role,
    },
    create: {
      documentId: args.id,
      userId: targetUser.id,
      role: args.role,
    },
  });
};

export const revokePermission: RevokePermission<{ id: number; userId: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  if (doc.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can revoke permissions");
  }

  return context.entities.Permission.delete({
    where: {
      documentId_userId: {
        documentId: args.id,
        userId: args.userId,
      },
    },
  });
};

import { type WebSocketDefinition } from "wasp/server/webSocket";

export let ioInstance: any = null;

export const webSocketFn: WebSocketDefinition = (io, context) => {
  ioInstance = io;

  io.on("connection", (socket) => {
    console.log("Client connected:", socket.id);

    socket.on("join-document", (docId) => {
      console.log(`Socket ${socket.id} joining document room document-${docId}`);
      socket.join(`document-${docId}`);
    });

    socket.on("edit-document", async ({ docId, content }) => {
      console.log(`Socket ${socket.id} editing document ${docId}`);

      try {
        await context.entities.Document.update({
          where: { id: Number(docId) },
          data: { content },
        });
      } catch (err) {
        console.error("Error saving document content in socket event:", err);
      }

      socket.to(`document-${docId}`).emit("document-edited", content);
    });

    socket.on("disconnect", () => {
      console.log("Client disconnected:", socket.id);
    });
  });
};

