            {shareSuccess && <p style={{ color: "green" }}>{shareSuccess}</p>}

            <h4>Permissions List</h4>
            <div id="permissions-list">
              {doc.permissions?.length === 0 ? (
                <p style={{ color: "#666" }}>This document is not shared with anyone yet.</p>
              ) : (
                <ul style={{ paddingLeft: "20px", margin: 0 }}>
                  {doc.permissions?.map((perm: any) => (
                    <li key={perm.id} style={{ marginBottom: "10px" }}>
                      <span style={{ marginRight: "15px" }}>
                        {perm.user.username} - <strong>{perm.role}</strong>
                      </span>
                      <button
                        onClick={() => handleRevokePermission(perm.userId)}
                        style={{ padding: "4px 8px", cursor: "pointer", color: "red", border: "1px solid red", borderRadius: "4px", backgroundColor: "transparent" }}
                      >
                        Revoke Access
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </section>
        )}
      </main>
    </div>
  );
}

import React, { useState } from "react";
import { useQuery, getDocuments, createDocument } from "wasp/client/operations";
import { useAuth, logout } from "wasp/client/auth";
import { Link } from "wasp/client/router";

export function MainPage() {
  const { data: user } = useAuth();
  const { data: documents, isLoading, error } = useQuery(getDocuments);
  const [newTitle, setNewTitle] = useState("");
  const [createError, setCreateError] = useState("");

  const handleCreateDocument = async (e: React.FormEvent) => {
    e.preventDefault();
    setCreateError("");
    if (!newTitle.trim()) {
      setCreateError("Title cannot be empty");
      return;
    }
    try {
      await createDocument({ title: newTitle });
      setNewTitle("");
    } catch (err: any) {
      setCreateError(err.message || "Failed to create document");
    }
  };

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px" }}>
      <header style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "30px", borderBottom: "1px solid #eee", paddingBottom: "10px" }}>
        <h1>Collaborative Document Editor</h1>
        {user && (
          <div style={{ display: "flex", alignItems: "center", gap: "15px" }}>
            <span>Welcome, <strong>{user.username}</strong>!</span>
            <button onClick={logout} style={{ padding: "5px 10px", cursor: "pointer" }}>Logout</button>
          </div>
        )}
      </header>

      <section style={{ marginBottom: "40px" }}>
        <h2>Create a New Document</h2>
        <form onSubmit={handleCreateDocument} style={{ display: "flex", gap: "10px", alignItems: "center" }}>
          <input
            type="text"
            id="document-title-input"
            placeholder="Document Title"
            value={newTitle}
            onChange={(e) => setNewTitle(e.target.value)}
            style={{ padding: "8px 12px", width: "300px", fontSize: "16px" }}
          />
          <button
            type="submit"
            id="create-document-btn"
            style={{ padding: "8px 16px", fontSize: "16px", cursor: "pointer" }}
          >
            Create Document
          </button>
        </form>
        {createError && <p style={{ color: "red", marginTop: "5px" }}>{createError}</p>}
      </section>

      <section>
        <h2>Your Documents</h2>
        {isLoading && <p>Loading documents...</p>}
        {error && <p style={{ color: "red" }}>Error loading documents: {error.message || String(error)}</p>}

        {documents && documents.length === 0 ? (
          <p>No documents found. Create one above to get started!</p>
        ) : (
          <ul style={{ listStyleType: "none", padding: 0 }}>
            {documents?.map((doc) => (
              <li
                key={doc.id}
                style={{
                  padding: "15px",
                  border: "1px solid #ddd",
                  borderRadius: "6px",
                  marginBottom: "10px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div>
                  <Link
                    to="/document/:id"
                    params={{ id: doc.id }}
                    style={{ fontSize: "18px", fontWeight: "bold", textDecoration: "none", color: "#0066cc" }}
                  >
                    {doc.title}
                  </Link>
                  <div style={{ fontSize: "12px", color: "#666", marginTop: "5px" }}>
                    Owner: {doc.owner.username === user?.username ? "You" : doc.owner.username} | Last updated: {new Date(doc.updatedAt).toLocaleString()}
                  </div>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

import { type GetDocuments, type GetDocument } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getDocuments: GetDocuments<void, any[]> = async (_args, context) => {
  const user = context.user;
  if (!user) {
    throw new HttpError(401, "Not authenticated");
  }

  return context.entities.Document.findMany({
    where: {
      OR: [
        { ownerId: user.id },
        {
          permissions: {
            some: {
              userId: user.id,
            },
          },
        },
      ],
    },
    include: {
      owner: true,
      permissions: {
        include: {
          user: true,
        },
      },
    },
    orderBy: {
      updatedAt: "desc",
    },
  });
};

export const getDocument: GetDocument<{ id: number }, any> = async (args, context) => {
  const user = context.user;
  if (!user) {
    throw new HttpError(401, "Not authenticated");
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: {
      owner: true,
      permissions: {
        include: {
          user: true,
        },
      },
      versions: {
        include: {
          author: true,
        },
        orderBy: {
          createdAt: "asc", // Display in chronological order
        },
      },
    },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === user.id;
  const userPermission = doc.permissions.find((p) => p.userId === user.id);

  if (!isOwner && !userPermission) {
    throw new HttpError(403, "Access Denied");
  }

  const role = isOwner ? "OWNER" : userPermission?.role;

  return {
    ...doc,
    role,
  };
};

import {
  type CreateDocument,
  type UpdateDocumentContent,
  type SaveVersion,
  type RestoreVersion,
  type ShareDocument,
  type RevokePermission,
} from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const createDocument: CreateDocument<{ title: string }, any> = async (args, context) => {
  const user = context.user;
  if (!user) {
    throw new HttpError(401, "Not authenticated");
  }
  if (!args.title || args.title.trim() === "") {
    throw new HttpError(400, "Title is required");
  }
  return context.entities.Document.create({
    data: {
      title: args.title,
      content: "",
      ownerId: user.id,
    },
  });
};

export const updateDocumentContent: UpdateDocumentContent<{ id: number; content: string }, any> = async (args, context) => {
  const user = context.user;
  if (!user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  const isOwner = doc.ownerId === user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === user.id && p.role === "EDIT"
  );
  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied: You do not have edit permission");
  }
  return context.entities.Document.update({
    where: { id: args.id },
    data: { content: args.content },
  });
};

export const saveVersion: SaveVersion<{ id: number; content: string }, any> = async (args, context) => {
  const user = context.user;
  if (!user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  const isOwner = doc.ownerId === user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === user.id && p.role === "EDIT"
  );
  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied: You do not have edit permission");
  }

  const version = await context.entities.Version.create({
    data: {
      documentId: args.id,
      content: args.content,
      authorId: user.id,
    },
  });

  await context.entities.Document.update({
    where: { id: args.id },
    data: { content: args.content },
  });

  return version;
};

export const restoreVersion: RestoreVersion<{ id: number; versionId: number }, any> = async (args, context) => {
  const user = context.user;
  if (!user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  const isOwner = doc.ownerId === user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === user.id && p.role === "EDIT"
  );
  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied: You do not have edit permission");
  }

  const version = await context.entities.Version.findUnique({
    where: { id: args.versionId },
  });
  if (!version || version.documentId !== args.id) {
    throw new HttpError(404, "Version not found");
  }

  const updatedDoc = await context.entities.Document.update({
    where: { id: args.id },
    data: { content: version.content },
  });

  const { ioInstance } = await import("./webSocket");
  if (ioInstance) {
    ioInstance.to(`document-${args.id}`).emit("document-restored", version.content);
  }

  return updatedDoc;
};

export const shareDocument: ShareDocument<{ id: number; username: string; role: string }, any> = async (args, context) => {
  const user = context.user;
  if (!user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  if (doc.ownerId !== user.id) {
    throw new HttpError(403, "Only the owner can share the document");
  }

  const targetUser = await context.entities.User.findUnique({
    where: { username: args.username },
  });
  if (!targetUser) {
    throw new HttpError(404, "User not found");
  }

  if (targetUser.id === user.id) {
    throw new HttpError(400, "You cannot share the document with yourself");
  }

  return context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId: args.id,
        userId: targetUser.id,
      },
    },
    update: {
      role: args.role,
    },
    create: {
      documentId: args.id,
      userId: targetUser.id,
      role: args.role,
    },
  });
};

export const revokePermission: RevokePermission<{ id: number; userId: number }, any> = async (args, context) => {
  const user = context.user;
  if (!user) {
    throw new HttpError(401, "Not authenticated");
  }
  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  if (doc.ownerId !== user.id) {
    throw new HttpError(403, "Only the owner can revoke permissions");
  }

  return context.entities.Permission.delete({
    where: {
      documentId_userId: {
        documentId: args.id,
        userId: args.userId,
      },
    },
  });
};
